"use client";
import { FormEvent, useState } from "react";
export default function InventoryPage(){const [tab,setTab]=useState("products");const [items,setItems]=useState([{name:"Coca-Cola",category:"Beverages",sell:1500,cost:1100,stock:10}]);const [name,setName]=useState("");const [category,setCategory]=useState("");const [sell,setSell]=useState("");const [cost,setCost]=useState("");const [stock,setStock]=useState("");function add(e:FormEvent){e.preventDefault();if(!name)return;setItems([...items,{name,category,sell:Number(sell),cost:Number(cost),stock:Number(stock)}]);setName("");setCategory("");setSell("");setCost("");setStock("");}return <main className="min-h-screen bg-[#0b0b0b] p-5 text-white md:p-8"><div className="mx-auto max-w-7xl"><h1 className="text-2xl font-semibold">Inventory</h1><section className="mt-6 rounded-2xl border border-white/10 bg-[#151515] p-5"><h2 className="font-semibold">Inventory Snapshot</h2><div className="mt-4 rounded-xl border border-dashed border-white/10 p-7 text-center text-sm text-white/35">Inventory analytics coming soon.</div></section><div className="mt-6 flex gap-2 border-b border-white/10">{["products","services"].map(x=><button key={x} onClick={()=>setTab(x)} className={`px-4 py-3 text-sm capitalize ${tab===x?"border-b-2 border-orange-500 text-orange-400":"text-white/45"}`}>{x}</button>)}</div>{tab==="products"?<><form onSubmit={add} className="mt-6 grid gap-3 rounded-2xl border border-white/10 bg-[#151515] p-5 md:grid-cols-3"><input value={name} onChange={e=>setName(e.target.value)} placeholder="Name" className="field"/><input value={category} onChange={e=>setCategory(e.target.value)} placeholder="Category (optional)" className="field"/><input value={sell} onChange={e=>setSell(e.target.value)} placeholder="Selling price" type="number" className="field"/><input value={cost} onChange={e=>setCost(e.target.value)} placeholder="Cost price" type="number" className="field"/><input value={stock} onChange={e=>setStock(e.target.value)} placeholder="Stock quantity" type="number" className="field"/><button className="rounded-xl bg-orange-500 px-4 py-3 text-sm font-semibold text-black">+ Add Item</button></form><div className="mt-6 overflow-x-auto rounded-2xl border border-white/10 bg-[#151515] p-5"><table className="w-full text-left text-sm"><thead className="text-xs text-white/40"><tr>{["NAME","CATEGORY","SELLING PRICE","COST PRICE","STOCK","ACTIONS"].map(x=><th key={x} className="px-3 py-3">{x}</th>)}</tr></thead><tbody>{items.map((x,i)=><tr key={`${x.name}-${i}`} className="border-t border-white/5"><td className="px-3 py-4">{x.name}</td><td className="px-3 py-4">{x.category||"Uncategorised"}</td><td className="px-3 py-4">₦{x.sell.toLocaleString()}</td><td className="px-3 py-4">₦{x.cost.toLocaleString()}</td><td className="px-3 py-4">{x.stock}</td><td className="px-3 py-4"><button className="mr-2 text-orange-400">Edit</button><button onClick={()=>setItems(items.filter((_,j)=>j!==i))} className="text-red-400">Delete</button></td></tr>)}</tbody></table></div></>:<div className="mt-6 rounded-2xl border border-white/10 bg-[#151515] p-10 text-center text-white/35">Services management coming soon.</div>}</div></main>}
